const fs=require('fs'),p=__dirname,files=['index.html','style.css','data.js','world.js'];let bad=files.filter(f=>!fs.existsSync(`${p}/${f}`));let all=files.map(f=>fs.readFileSync(`${p}/${f}`,'utf8')).join('\n');for(const x of ['SIS_3D_DATA','data-room','data-part','data-transform','transforming','prefers-reduced-motion','aria-live'])if(!all.includes(x))bad.push(x);if(/fetch\(|XMLHttpRequest|WebSocket|localStorage|sessionStorage|wallet|provider|openrouter|https?:\/\//i.test(all))bad.push('external-or-persistence-token');console.log(`SIS 3D prototype QA: ${bad.length?'FAIL '+bad.join(', '):'PASS (4 files, local-only markers present)'}`);process.exit(bad.length?1:0);